"use client";

import { loadFont as loadDisplay } from "@remotion/google-fonts/Geist";
import type React from "react";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  BEAM_GAP,
  DEFAULT_WORD,
  FIRST_LOCK,
  HOLD,
  LOCK_STEP,
  type RingAlignElementId,
  ringAlignTimeline,
  ringCount,
  TAIL,
  TAIL_DELAY,
} from "./timeline";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface RingAlignProps {
  /** Word revealed in the channel once every slot lines up. */
  word?: string;
  /** Number of concentric rings. */
  rings?: number;
  accent?: string;
  /** Frames between rings locking into place. */
  stagger?: number;
  /** Radius of the ring dots, in px at 720p. */
  dotSize?: number;
  /** Solid color for the word and ring dots in place of the theme. */
  ink?: string;
  /** Solid fill in place of the toned ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the word. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Size of the rings and word, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single ring locks and the beam, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<RingAlignElementId>;
}

export const ringAlignLength = (rings = 6, stagger = LOCK_STEP) =>
  FIRST_LOCK + (rings - 1) * stagger + BEAM_GAP + TAIL_DELAY + TAIL + HOLD;

const LOCK = Easing.bezier(0.3, 0.55, 0.32, 1.05);
const WIPE = Easing.bezier(0.22, 1, 0.36, 1);
const TAIL_EASE = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function hash(n: number): number {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function circle(x: number, y: number, r: number) {
  const rs = r.toFixed(2);
  const d = (2 * r).toFixed(2);
  return `M${(x - r).toFixed(1)} ${y.toFixed(1)}a${rs} ${rs} 0 1 0 ${d} 0a${rs} ${rs} 0 1 0 -${d} 0`;
}

function wrap(a: number) {
  let v = a % (Math.PI * 2);
  if (v > Math.PI) v -= Math.PI * 2;
  if (v < -Math.PI) v += Math.PI * 2;
  return v;
}

/* gradients.sh "radial-glow" palette: the beam that runs the channel, and
   the fill the word keeps once the beam has passed. */
const GLOW = ["#f3f1ff", "#9db4ff", "#5a46cb", "#1d1240"] as const;

function Grain({ opacity, light }: { opacity: number; light: boolean }) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={`${uid}-grain`}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency={0.85}
          numOctaves={2}
          seed={3}
        />
        <feColorMatrix
          type="matrix"
          values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1 0"
        />
      </filter>
      <rect
        width="100%"
        height="100%"
        filter={`url(#${uid}-grain)`}
        opacity={opacity}
        style={{ mixBlendMode: light ? "multiply" : "screen" }}
      />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function RingAlign(props: RingAlignProps) {
  const {
    word = DEFAULT_WORD,
    rings = 6,
    accent = "#3B5BFD",
    dotSize = 3.1,
    ink,
    background,
    fontFamily = display,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    ringAlignTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const isLight = theme === "light";
  const bg = isLight ? "#F5F4F0" : "#0A0A0B";
  const fg = ink ?? (isLight ? "#141416" : "#EEEEF0");
  const u = Math.min(W, H) / 720;
  const n = ringCount(rings);
  const cx = W / 2;
  const cy = H / 2;

  const band = H * 0.175;
  const pad = 9 * u;
  const rIn = H * 0.165;
  const rOut = H * 0.44;
  const dotR = dotSize * u;
  const pitch = 17 * u;

  const beam = tl.get("beam");
  const beamStart = beam.start;

  const ringPaths: { d: string; opacity: number }[] = [];
  for (let k = 0; k < n; k++) {
    // Outer ring locks first, the innermost last.
    const r = rOut - ((rOut - rIn) * k) / (n - 1);
    const count = Math.round((Math.PI * 2 * r) / pitch);
    const gap = 2 * Math.asin(Math.min(0.98, (band / 2 + pad) / r));
    const ring = tl.get(`ring:${k}`);
    const lockAt = ring.start;
    const spin = ring.beat("spin");
    const dir = k % 2 === 0 ? 1 : -1;
    const offset = dir * Math.PI * (1.35 + hash(k * 4.1) * 0.5);
    const x = Math.min(1, Math.max(0, (t - (lockAt - spin)) / spin));
    let rot = offset * (1 - LOCK(x));
    const since = t - lockAt;
    if (since > 0) {
      rot +=
        -dir * 0.012 * Math.sin((since / 7) * Math.PI) * Math.exp(-since / 4);
    }
    const lightAt = ring.beat("lightAt");
    const lit = interpolate(
      since,
      [lightAt, lightAt + ring.beat("light")],
      [0.42, 1],
      CLAMP,
    );
    const segs: string[] = [];
    for (let j = 0; j < count; j++) {
      const a = (j / count) * Math.PI * 2 + rot;
      const local = wrap((j / count) * Math.PI * 2);
      const toSlot = Math.min(Math.abs(local), Math.abs(wrap(local - Math.PI)));
      if (toSlot < gap / 2) continue;
      segs.push(circle(cx + Math.cos(a) * r, cy + Math.sin(a) * r, dotR));
    }
    ringPaths.push({ d: segs.join(""), opacity: lit });
  }

  const head = W * WIPE(interpolate(t, [beam.start, beam.end], [0, 1], CLAMP));
  const tail =
    W *
    TAIL_EASE(
      interpolate(
        t,
        [
          beamStart + beam.beat("tailAt"),
          beamStart + beam.beat("tailAt") + beam.beat("tail"),
        ],
        [0, 1],
        CLAMP,
      ),
    );
  const fontSize = band * 0.72;
  const dot = word.endsWith(".");
  const body = dot ? word.slice(0, -1) : word;
  const [g0, g1, g2, g3] = GLOW;
  const drift = interpolate(
    t,
    [beamStart, beamStart + beam.beat("drift")],
    [0, 1],
    CLAMP,
  );
  const wordFill = ink
    ? `linear-gradient(${ink}, ${ink})`
    : isLight
      ? `linear-gradient(90deg, ${g2} ${(-10 + 20 * drift).toFixed(1)}%, ${g3} ${(45 + 10 * drift).toFixed(1)}%, ${g2} ${(110 + 10 * drift).toFixed(1)}%)`
      : `linear-gradient(90deg, ${g1} ${(-10 + 20 * drift).toFixed(1)}%, ${g0} ${(45 + 10 * drift).toFixed(1)}%, ${g1} ${(110 + 10 * drift).toFixed(1)}%)`;
  const beamFill = `linear-gradient(90deg, ${g3} 0%, ${g2} 45%, color-mix(in oklab, ${g2} 55%, ${g1}) 88%, ${g1} 98%, ${g0} 100%)`;
  const wordLayer = (fill: string, l: number, r: number) => (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: cy - band / 2,
        width: W,
        height: band,
        clipPath: `inset(0 ${(W - r).toFixed(1)}px 0 ${l.toFixed(1)}px)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily,
          fontWeight: 500,
          fontSize,
          letterSpacing: "-0.035em",
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          paddingBottom: fontSize * 0.04,
          paddingRight: fontSize * 0.04,
          backgroundImage: fill,
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          color: "transparent",
        }}
      >
        {body}
        {dot ? (
          <span
            style={{
              WebkitTextFillColor: fill.includes("#FFFFFF")
                ? "#FFFFFF"
                : accent,
            }}
          >
            .
          </span>
        ) : null}
      </div>
    </div>
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor:
          background === "transparent" ? undefined : (background ?? bg),
        backgroundImage:
          background !== undefined
            ? undefined
            : isLight
              ? `radial-gradient(34% 58% at 50% 50%, color-mix(in oklab, ${GLOW[1]} 16%, transparent) 0%, transparent 100%), radial-gradient(70% 70% at 50% 50%, #FBFAF7 0%, ${bg} 72%)`
              : `radial-gradient(34% 58% at 50% 50%, color-mix(in oklab, ${GLOW[2]} 22%, transparent) 0%, transparent 100%), radial-gradient(70% 70% at 50% 50%, #121215 0%, ${bg} 72%)`,
        overflow: "hidden",
      }}
    >
      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {ringPaths.map((p, k) => (
            <path
              key={`ring-${k.toString()}`}
              d={p.d}
              fill={fg}
              opacity={p.opacity}
            />
          ))}
        </svg>
        {tail > 0 ? wordLayer(wordFill, 0, tail) : null}
        {head > tail + 0.5 ? (
          <div
            style={{
              position: "absolute",
              left: tail,
              top: cy - band / 2,
              width: head - tail,
              height: band,
              backgroundImage: beamFill,
            }}
          />
        ) : null}
        {head > tail + 0.5
          ? wordLayer("linear-gradient(#FFFFFF, #FFFFFF)", tail, head)
          : null}
      </ScaleLayer>
      {grain ? (
        <Grain opacity={isLight ? 0.045 : 0.06} light={isLight} />
      ) : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// Concentric rings of dots spin into alignment, outermost first, until their
// gaps line up into a channel; a beam then wipes the word through it. Frames
// on the 30 fps scene timeline, after `delay` and `speed`. The ids are
// public: a saved `timing` prop refers to them.

export type RingAlignElementId = `ring:${number}` | "beam";

export interface RingAlignTimingProps {
  word?: string;
  rings?: number;
  stagger?: number;
}

export const DEFAULT_WORD = "Aligned.";
export const FIRST_LOCK = 30;
export const LOCK_STEP = 8;
export const BEAM_GAP = 4;
export const BEAM = 14;
export const TAIL_DELAY = 8;
export const TAIL = 16;
export const HOLD = 32;

/** Rings drawn for a `rings` prop: three to nine. */
export function ringCount(rings: number) {
  return Math.max(3, Math.min(9, Math.round(rings)));
}

// `ring:<k>` locks ring `k` (outermost first) at its start, after spinning
// in over `spin` frames from the top of the scene; it lights from `lightAt`
// over `light` and runs until the next ring locks. A chain. `beam` wipes the
// word in over its length after the last lock, the tail follows from
// `tailAt` over `tail`, and the word's gradient drifts over `drift`.
export const ringAlignTimeline = defineTimeline<
  RingAlignElementId,
  RingAlignTimingProps
>(({ word = DEFAULT_WORD, rings = 6, stagger = LOCK_STEP }) => {
  const n = ringCount(rings);
  const elements: TimelineElement<RingAlignElementId>[] = [];
  for (let k = 0; k < n; k++) {
    const lockAt = FIRST_LOCK + k * stagger;
    elements.push({
      id: `ring:${k}`,
      lane: "Rings",
      label: `Ring ${k + 1}`,
      start: lockAt,
      length: k < n - 1 ? stagger : BEAM_GAP,
      follows: k > 0 ? `ring:${k - 1}` : undefined,
      beats: { spin: lockAt, lightAt: -2, light: 8 },
    });
  }
  const lastLock = FIRST_LOCK + (n - 1) * stagger;
  elements.push({
    id: "beam",
    lane: "Word",
    label: word,
    start: lastLock + BEAM_GAP,
    length: BEAM,
    follows: `ring:${n - 1}`,
    beats: { tailAt: TAIL_DELAY, tail: TAIL, drift: TAIL_DELAY + TAIL + HOLD },
  });
  return elements;
});
